\begin{proposition}[Flat scales and a measure of centers]
\label{prop:flat-scales}
Suppose that $V$ is a stationary integral $m$-varifold in an open
subset of $\R^{m+n}$ and that
\[
 m-1<s<\dim_{\Hh}\Sing(V).
\]
After a translation there exist a fixed point $0\in\Sing(V)$, an
integer $Q\ge1$, an $m$-plane $\Pi$ through zero, radii $L_i\downarrow0$,
and positive Radon measures $\sigma_i$ such that
\begin{equation}
 \label{eq:flat-targets}
 \Theta_V(0)=Q,\qquad V_{L_i}\rightharpoonup Q|\Pi|
 \quad\hbox{locally in }\R^{m+n}.
\end{equation}
Each $\sigma_i$ is supported in $\overline{\mathbf B}_1$ on singular
points of $V_{L_i}$ having density exactly $Q$. There are constants
$c,C>0$, independent of $i$, for which
\begin{equation}
 \label{eq:center-measure-bounds}
 \sigma_i(\mathbf B_u(X))\le C u^s
 \quad(X\in\R^{m+n},\ u>0),\qquad
 c\le\sigma_i(\overline{\mathbf B}_1)\le C.
\end{equation}
\end{proposition}

\begin{theorem}[Signed excess]\label{thm:signed-input}
Fix an integer $Q\ge1$ and $\kappa>0$. In the normal-cylinder setting above, scale a
physical base radius $l$ to one and suppose $B_4$ is available. Set
$\tau=|M|+D+\Lambda$. If
\begin{equation}\label{eq:signed-hypotheses}
 \tau(B_4)\le d=e^{-T},\qquad
 l+\sup|z_{\mathrm{phys}}|\le d^\kappa,
\end{equation}
where the supremum is over the restricted support above the available
chart, then, for $T$ sufficiently large,
\begin{equation}\label{eq:signed-input}
 \int w\,\dd(2M-D-C_Q\Lambda)
       \le d\exp[-F_Q(T)]
\end{equation}
whenever $w$ is supported in $B_1$, $0\le w\le1$, and $\Lip w\le1$.
The finite derivative order $J$, threshold, and constants depend only
on the stated fixed data. For a subchart in inherited frames, the second
condition is imposed on $\gamma$ in Equation~\eqref{eq:physical-gamma}.
For a flat reference, take $\Lambda=0$ and omit the second condition.
\end{theorem}

\begin{lemma}[Inward control]\label{lem:inward-control}
There is a fixed large $K$ such that, writing $v_0=\dot A/H$,
\begin{equation}\label{eq:large-frequency}
 |P|\ge K\quad\Longrightarrow\quad
 q_*/|P|\ge c\min(|P|,\eta^{-1}),\qquad v_0\ge cq_*.
\end{equation}
When $K\le P\le T^4$,
\begin{equation}\label{eq:moderate-frequency}
 \dot P\ge-C(rP+gP^2).
\end{equation}
A lower bound for $P$ at the smaller-radius endpoint of a finite
interval gives a lower bound throughout that interval. On an interval
extending to zero, $P$ is bounded below for all sufficiently small radii.
If at a sufficiently small starting radius $r_0$ one has $P_0\le T_0^2$,
then inward throughout the interval
\begin{equation}\label{eq:inward-upper}
 P\le \exp(1)\max(K,P_0).
\end{equation}
Such a starting radius exists on every interval extending to zero.
Finally, wherever $|P|\le C_0$ and $\eta$ is sufficiently small
depending on $C_0$, every fixed bounded-ratio subinterval satisfies
\begin{equation}\label{eq:height-doubling}
 H(r')\asymp H(r''),\qquad
 \int q_*\,\dd\log r\le C.
\end{equation}
The constants in the last conclusion depend on $C_0$ and the radius
ratio, not on the position of the interval.
\end{lemma}

\begin{proposition}[Uniform comparison at the targets]\label{prop:target-frequency}
All sufficiently late $L_i$ belong to intervals
\eqref{eq:target-interval}. After passing to a subsequence, either one
interval extends to zero and contains all these targets, or the indices
of their covering intervals tend to infinity. In the latter case,
on each sufficiently late covering interval,
\begin{equation}\label{eq:uniform-frequency-range}
 |P(r)|\le C\qquad(B_*b\le r\le r_*),
\end{equation}
and \eqref{eq:height-doubling} holds there with uniform constants.
In the former case the same conclusions hold on the sufficiently
small-radius part of the fixed interval.
\end{proposition}

\begin{proposition}[Dimension reduction for height and stress]
\label{prop:measure-reduction}
Let $\Omega\subset\R^m$ be connected and open. Let $\nu$ be a
nonzero nonnegative Radon measure, $f$ an $\R^m$-valued Radon measure,
$\beta$ a symmetric matrix-valued Radon measure, and $\mathfrak m$
a signed Radon measure on $\Omega$. Suppose that
\begin{equation}
 \label{eq:abstract-psd}
 \begin{pmatrix}\nu&f^{\rm t}\\ f&\beta\end{pmatrix}
 \quad\hbox{is a positive semidefinite matrix-valued measure},
 \qquad d_0=\tr\beta,
\end{equation}
and that, in distributions,
\begin{equation}
 \label{eq:abstract-identities}
 \nabla\nu=2f,\qquad \diver f=d_0,\qquad
 \int\diver X\,\dd\mathfrak m
       =\int DX:\dd\beta
 \quad(X\in C_c^\infty(\Omega;\R^m)).
\end{equation}
Assume also that for every open $\Omega'\Subset\Omega$ there is a
constant $C_{\Omega'}$ such that, on $\Omega'$,
\begin{equation}
 \label{eq:abstract-sign}
 2\mathfrak m\le d_0,\qquad |\mathfrak m|\le C_{\Omega'}d_0.
\end{equation}
Let $Z\subset\Omega$ be a Borel set such that for each $x\in Z$,
\begin{equation}
 \label{eq:abstract-center}
 2l^2\int\phi_{x,l}\,\dd\mathfrak m
       \ge\int\psi_{x,l}\,\dd\nu
\end{equation}
for every sufficiently small $l>0$. Then
$\dim_{\Hh}Z\le m-1$.
\end{proposition}

\begin{lemma}[A strict inner gap]\label{lem:gap}
After choosing the tolerances sufficiently small, there are constants
\(\varepsilon_1>0\) and \(C<\infty\) such that, at all sufficiently late
times,
\begin{equation}\label{eq:strict-gap}
\phi/r\ge A/B+\varepsilon_1\quad(0<r\le Y_1\theta),
\qquad \phi(Y_1\theta,t)\le C\theta.
\end{equation}
\end{lemma}

\begin{lemma}[Bounds used in the dimension estimate]\label{lem:uniform}
The construction parameters can be chosen so that, for all sufficiently
large \(q\) and all sufficiently late times,
\begin{equation}\label{eq:uniform}
|z-1|\le C_0/q,\qquad r|u_r|\le2,\qquad
(p-1)r^2e^{-2u}\le(q-1)(1+C_0/q)
\end{equation}
on \(0<r\le\sqrt\delta\), where \(C_0\) is a numerical constant
independent of \(q\) and \(k\). This interval is below the equator.
\end{lemma}

\begin{lemma}[Global ratio and parabolic annuli]\label{lem:annuli}
For a flow chosen as above, \(\phi/r\ge c_0>0\) globally off the poles.
For every fixed \(0<a_1<a_2<\infty\), at all sufficiently late times,
\begin{equation}\label{eq:annular-ricci}
|\Ric|\le C_{a_1,a_2}\delta^{\nu-1}
\qquad(a_1\sqrt\delta\le r\le a_2\sqrt\delta).
\end{equation}
The constants and the required starting time may depend on the annulus.
\end{lemma}

\begin{proposition}\label{prop:full-curvature}
For every flow with the choices made above, and \(q\) sufficiently large,
there is a constant \(C\), allowed to depend on that flow, such that
\begin{equation}\label{eq:full-curvature}
(r^2+\theta^2)|\Rm|\le C
\end{equation}
on \(M\times[0,T)\).
\end{proposition}

\begin{lemma}\label{lem:r-curvature}
There is a time-independent constant \(C\) such that \(r^2|\Rm|\le C\).
\end{lemma}

\begin{lemma}[Size of the pole orbit]\label{lem:pole-size}
At all sufficiently late times,
\begin{equation}\label{eq:pole-size}
c\theta\le\phi(0,t)\le C\theta.
\end{equation}
Moreover \(\phi(r,t)\ge c\theta\) for \(0\le r\le Y_1\theta\).
\end{lemma}

\begin{lemma}[Radial slope at the cap scale]\label{lem:cap-slope}
For sufficiently large \(q\), at late times,
\begin{equation}\label{eq:cap-slope}
0\le1-v\le C r/\theta\qquad(0\le r\le\theta).
\end{equation}
\end{lemma}

\begin{lemma}\label{lem:largeq-derivatives}
For all sufficiently large \(q\), and sufficiently late times,
\begin{equation}\label{eq:largeq-derivatives}
|rz_r|\le Cq^{-1/2},\qquad r^2|u_{rr}|\le Cq^{1/2}
\quad\left(0<r\le\tfrac18\sqrt\delta\right),
\end{equation}
where \(C\) is independent of both \(q\) and \(k\).
\end{lemma}

\begin{proposition}\label{prop:reaction}
At late times on \(0<r\le\frac18\sqrt\delta\), the reaction quotient
\[
c(x,t)=\frac{2\langle\Rm(\Ric),\Ric\rangle}{|\Ric|^2}
\quad\text{where }|\Ric|>0
\]
satisfies both bounds
\begin{equation}\label{eq:reaction-two}
c\le\frac{2(q-1)+C\sqrt q}{r^2},\qquad
c\le\frac{C_*}{\theta^2}.
\end{equation}
Here \(C\) is independent of \(q,k\); \(C_*\) may depend on the entire
chosen flow. The second bound holds at the pole orbits as well.
Globally at positive \(r\), one also has \(c\le D_1/r^2\) for some
flow-dependent \(D_1>0\).
\end{proposition}

\begin{proposition}\label{prop:ricci-barrier}
There is a constant \(C\) such that, at all sufficiently late times,
\begin{equation}\label{eq:inner-ricci}
|\Ric|\le C\delta^L(r^2+b_0\theta^2)^{-a/2}
\qquad(0\le r\le\xi\sqrt\delta).
\end{equation}
In particular,
\begin{equation}\label{eq:ricci-power}
|\Ric|\le Cr^{-e}\qquad(0<r\le\xi\sqrt\delta).
\end{equation}
\end{proposition}

\begin{proposition}\label{prop:scalar-inner}
The scalar curvature is uniformly bounded above on
\(0\le r\le\xi\sqrt\delta\) at late times.
\end{proposition}

\begin{proposition}\label{prop:exterior}
There is a constant \(C\) such that
\(|\Ric|\le C\) on \(r\ge\xi\sqrt\delta\) at late times.
\end{proposition}

\begin{lemma}[Minimal fits and their compatibility]
 \label{ce:fit}
Fix a finite derivative order $J\ge6$.  There are an integer
$k_0>J+4$, integers $q,N$, and constants $C,m_*>0$, depending only on the
dimensions, $Q$, and these fixed orders, with the following property.
For $0<m_0<m_*$ and sufficiently small initial height and mass error,
one can make the following construction simultaneously for every
$x\in B_5$.

At the scales $\ell_j=2^{-j}$ construct smooth minimal graphs
$S_{x,j}=\operatorname{graph}f_{x,j}$ over $B_{80\ell_j}(x)$, and stop at
the first scale for which
\begin{equation}
 \label{ce:accept}
 \sup\bigl\{|X_v-f_{x,j}(X_h)|:
       X\in\spt\mu,\ X_h\in B_{64\ell_j}(x)\bigr\}
       \le m_0\ell_j^{k_0}
\end{equation}
fails.  If there is no failure, all scales are constructed.  The graph at
the first failed scale is included in the construction.  On fixed
interior enlargements of its test ball, every constructed graph satisfies
the height upper bound $C m_0\ell_j^{k_0}$, the tilt and mass-defect bounds
\begin{equation}
 \label{ce:fitenergy}
 \ell_j^{-m}\bigl(D+|M|\bigr)(B_{70\ell_j}(x))
       \le C a_j^2,
 \qquad a_j=m_0\ell_j^{k_0-1},
\end{equation}
and the following centering estimate.  For each smooth vector test
$\zeta$ supported in $B_{70}$,
\begin{equation}
 \label{ce:moment}
 \left|\ell_j^{-m}\int
   \frac{X_v-f_{x,j}(X_h)}{\ell_j}\cdot
   \zeta\left(\frac{X_h-x}{\ell_j}\right)\,\dd\mu(X)\right|
       \le C a_j^2\|\zeta\|_{H^q}.
\end{equation}
The same assertion holds in normal coordinates over $S_{x,j}$, with
base volume in the definition of the distribution.

Every graph has physical derivatives of orders $1,\ldots,J$ bounded by
$Cm_0$ in the fixed initial coordinates.  If two constructed fits have
comparable scales and a common interior region containing a ball of
radius comparable to $\ell$, then, on a fixed smaller ball in that
region,
\begin{equation}
 \label{ce:overlap}
 \|D^i(f-f')\|_{L^\infty}
       \le C m_0^2\ell^{2k_0-1-i},\qquad 0\le i\le J.
\end{equation}
The constants in this last assertion can depend on the fixed scale ratio
and the fixed interior room.  No measurability of $x\mapsto f_{x,j}$ is
required.
\end{lemma}

\begin{proposition}[Weights up to the boundary of the ball]
 \label{ce:weights}
Either the support lies on $S$ in a neighborhood of $0$, or there
exist $r_0>0$, $c,C>0$, and a finite $J_0$ such that, for every
$0<r<r_0$,
\begin{equation}
 \label{ce:height}
 0<\delta(r)\le Cr,
 \qquad c\delta(r)^{J_0}\le\frac{H(r)}{r^2}
                         \le C\delta(r)^2.
\end{equation}
In the latter alternative, throughout $\rho<r$ one also has
\begin{equation}
 \label{ce:pointwisecurvature}
 |H_S|+|\nabla H_S|\le C\delta(r)r,
\end{equation}
and
\begin{equation}
 \label{ce:curvature}
 r^{-m}\int\phi_r\bigl(|H_S|^2+|\nabla H_S|^2\bigr)\,\dd\mu
       \le C r^{-m}\int\phi_r|z|^2\,\dd\mu.
\end{equation}
The constants may depend on the fixed center construction.  One may
take any fixed $J_0\ge2+(m+p-1)/k_0$ after changing $c$.
\end{proposition}

\begin{corollary}[Regularity when height vanishes]\label{ce:constancy}
If the support lies on the center $S$ in a neighborhood of the origin,
then the origin is regular.
\end{corollary}

\begin{lemma}[Future envelope]
\label{ex:envelope}
Set
\begin{equation}
 I(s)=\max\left\{
   \sup_{s\le v\le\rho}(s/v)^K A(v),\,
   (s/\rho)^K\rho^2d\rho^{-2m-4}\right\},
 \qquad a(s)=\log\frac{s^2}{I(s)}.
 \label{ex:future}
\end{equation}
Starting at a threshold scale \(s_0\), stop at the first scale
\(s_*\) with \(a(s_*)=T/2\). This scale exists, and on the path
\([s_0,s_*]\) one has
\begin{equation}
 a(s_0)=a_0+O(1),\qquad a(s)\ge a_0-O(1),\qquad
 v^2\tau_v\le C(v/s)^K I(s)\quad(s\le v\le\rho).
 \label{ex:dilations}
\end{equation}
The functions \(I,a\) are locally Lipschitz in \(\log s\). Almost
everywhere they satisfy
\begin{equation}
 \begin{cases}
 I=A,\quad \dot I=\dot A,&\text{on the reset set }\{I=A\},\\
 \dot I=KI,&\text{on its complement},
 \end{cases}
 \qquad
 |\dot a|+\dfrac{|\dot I|+|\dot Z|}{I}\le C.
 \label{ex:derivatives}
\end{equation}
Moreover \(\dot Z/I\) is locally Lipschitz, with derivative bounded
by \(C\). For every fixed \(P\), weighted scalar control gives
\begin{equation}
 |M|_s\le C(D_s+\Lambda_s)+a^{-P}I(s)/s^2.
 \label{ex:weighted-scalar}
\end{equation}
All constants are uniform in the contact and the bottom.
\end{lemma}

\begin{proposition}[Low-frequency barrier]
\label{ex:barrier}
Along every path in \Cref{ex:envelope}, the wells can be chosen
piecewise constantly, with at most \(Q-1\) mergers. There is a
positive piecewise smooth parameter \(k\), bounded above by a small
fixed constant and satisfying between mergers
\begin{equation}
 \frac{k_a}{k}=q=-\frac{k}{a^2},
 \label{ex:k-evolution}
\end{equation}
such that the comparison \eqref{ex:comparison} holds.
Here \(C_1\) is fixed and sufficiently large. Uniformly along the
path, \(\log(1/k)=o(a_0)\) as \(T\to\infty\).
Before any hypothetical first failure of the barrier, the following
estimates hold, with \(\mathcal E\le a^{-P_0/2}\):
\begin{align}
 \dot U&\le2s^2D_s+Cs^2D_{\mathrm{tr}}+\mathcal E I,
 \label{ex:moment-derivative}\\
 s^2R_s&\ge4k(s^2D_s-Cs^2D_{\mathrm{tr}})
             -4k^2U-\mathcal E kI.
 \label{ex:radial-bound}
\end{align}
With more than one well, in addition,
\begin{equation}
 \dot Z+c_2\frac{(\log a)^2}{a}s^2D_{\mathrm{tr}}
       \le a^{-P_0}I.
 \label{ex:transition}
\end{equation}
The transition terms are absent with one well. By increasing the
fixed exponents in the construction, \(\mathcal E\) can be smaller
than any prescribed inverse power of \(a\).
\end{proposition}

\begin{lemma}[Frequency inequalities]\label{in:frequency}
With a dot denoting differentiation with respect to $\log r$, the
quantities in \eqref{in:variables} satisfy
\begin{align}
 n_*&\leq\sqrt{q_*}+Cr^2+\eta n_*,\label{in:normalfrequency}\\
 \left|\frac{\dot A}{H}-(2P-n_*+q_*)\right|
  &\leq C\{r\sqrt{q_*}+r^2(1+n_*)\}+\eta(n_*+q_*),
                         \label{in:horizontalfrequency}\\
 -m\leq\frac{\dot H}{H}
  &\leq2n_*+Cr+\eta(n_*+q_*).\label{in:heightfrequency}
\end{align}
\end{lemma}

\begin{proposition}[The inward bootstrap]\label{in:bootstrap}
On all sufficiently small radii, $P$ is bounded above and below.
For each fixed $\lambda\in(0,1)$ there are constants $C_\lambda,c_\lambda>0$
such that
\begin{equation}\label{in:doubling}
 c_\lambda H(r)\leq H(\lambda r)\leq C_\lambda H(r),
 \qquad
 \int_{\lambda r}^{r}q_*(v)\,\frac{\dd v}{v}\leq C_\lambda.
\end{equation}
There is a sequence $r_j\downarrow0$ on which both $n_*(r_j)$ and
$q_*(r_j)$ are bounded.
\end{proposition}

\begin{proposition}[Vanishing height at a typical point]\label{in:finish}
The positive-height alternative at the origin is impossible.
Consequently every point satisfying the typical-point hypotheses \eqref{ce:typical} is regular.
\end{proposition}

\begin{lemma}[Monotonicity and mean value]\label{lt:monotonicity}
Let $V$ be stationary and integral in an open Euclidean set.  If
$p\in\spt\mu$ and $\overline{\mathbf B_r(p)}$ lies in that set, then
\begin{equation}\label{eq:lt-lower-mass}
 \mu(\mathbf B_r(p))\ge\omega_m r^m.
\end{equation}
If $u\ge0$ is a $C^2$ ambient function with
$\tr(P_TD^2u)\ge0$ for $V$-almost every $(x,T)$ in the ball, then
\begin{equation}\label{eq:lt-mean-value}
 u(p)\le \frac{1}{\omega_m r^m}
                  \int_{\mathbf B_r(p)}u\,\dd\mu.
\end{equation}
The same assertion holds for continuous functions satisfying the corresponding
weak subharmonicity inequality.
\end{lemma}

\begin{lemma}[Curved horizontal first variation]\label{lt:curvedvariation}
For a compactly supported tangent field $X$ on $S$,
\begin{equation}\label{eq:lt-curvedvariation}
 \begin{split}
 &\left|\int\Div_SX\,\dd M-\int B:\nabla^SX\,\dd\mu\right|\\
 &\quad\le C\int\Big\{|z_{\rm phys}|e|\nabla^SX|
 +\big[(|\nabla^\perp H_S|+|z_{\rm phys}|)|z_{\rm phys}|
       +\sqrt e\,|z_{\rm phys}|\big]|X|\Big\}\dd\mu.
 \end{split}
\end{equation}
The integrands containing tensors are evaluated at $q$, with the base field
pulled back by $\pi$.  In coordinates scaled by $l$, the right side is
bounded by
\begin{equation}\label{eq:lt-scaledvariation}
 C\gamma\int(e+\lambda)(|\nabla X|+|X|)\,\dd\mu.
\end{equation}
Here and below a dimensionless scaled test field is used in a scaled
identity.
\end{lemma}

\begin{lemma}[Projection and integer counts]\label{lt:jacobian}
The tangential Jacobian of $\pi$ is
\begin{equation}\label{eq:lt-jacobian}
 J_\pi=\frac{\sqrt{\det P_{hh}}}{\det J_z},\qquad
 |J_\pi-1|\le C(e+\lambda).
\end{equation}
There is a nonnegative integer-valued function $N$ on the base, finite
almost everywhere, such that
\begin{equation}\label{eq:lt-integer-measure}
 \pi_\#(J_\pi\mu)=N\vol_S,
 \qquad |\nu-N\vol_S|\le C(D+\Lambda).
\end{equation}
The inequalities are measure inequalities on every relatively compact base
set.  Moreover, for sufficiently small $e$,
\begin{equation}\label{eq:lt-signed-jacobian}
 2(1-J_\pi)-e\le Ce^2+C(|z_{\rm phys}|^2+|H_S|^2).
\end{equation}
\end{lemma}

\begin{lemma}[Scalar potential estimate]\label{lt:potential}
Suppose a finite scalar measure $v$ on $B_4\subset\R^m$ satisfies
\begin{equation}\label{eq:lt-gradient-equation}
 \partial_jv=\sum_i\partial_i F_{ij}+g_j,
 \qquad \sum_{ij}|F_{ij}|(B_4)+\sum_j|g_j|(B_4)\le\epsilon.
\end{equation}
Then there is a real constant $c$ such that the density $v_{\rm ac}$ obeys
\begin{equation}\label{eq:lt-weak-one}
 |\{y\in B_2:|v_{\rm ac}(y)-c|>t\}|
                     \le C\epsilon/t\quad(t>0),
\end{equation}
and, for every smooth test supported in $B_2$,
\begin{equation}\label{eq:lt-distribution-control}
 |\langle v-c\,\dd y,\varphi\rangle|
                     \le C\epsilon\|\varphi\|_{C^{k}},
\end{equation}
where $k$ is a fixed integer depending only on $m$.  Fixed changes of the
radii give the same conclusion.
\end{lemma}

\begin{lemma}[Ordered witness scales]\label{pk:witnesses}
Consider a contact path and a merger-free traversal of $[B,2B]$
provided by \Cref{ex:bands}, with $k\ge B^{-\eps_0}$ throughout the
traversal.  Given a sufficiently small fixed number $\vartheta>0$,
there are at least $cB^{1/2}$ scales $s_j$, ordered in outward time,
whose levels satisfy
\begin{equation}\label{pk:level-spacing}
 B+1<a(s_j)<2B-1,\qquad
 a(s_{j+1})-a(s_j)\ge B^{1/3}.
\end{equation}
If more than one well remains, these scales satisfy
\begin{equation}\label{pk:multi-witness}
 D_{s_j}\ge c e^{-a(s_j)},\qquad
 D_{\mathrm{tr}}(s_j)\le\vartheta e^{-a(s_j)}.
\end{equation}
If only one well remains, they satisfy
\begin{equation}\label{pk:single-witness}
 D_{s_j}\ge B^{-\eps_0}e^{-a(s_j)}.
\end{equation}
The constants are independent of the contact and of the positive
bottom scale.  The large threshold for $B$ may depend on $\eps_0$.
\end{lemma}

\begin{lemma}[Charging the contact measure]\label{pk:contact-charge}
Let $h$ and $\nu$ be finite positive measures on $\R^m$, and let
$\mathcal C$ be a set of contact centers.  For each of its
contacts suppose there are radii $0<u_x\le s_x$ with
\begin{equation}\label{pk:charge-hypotheses}
 \nu_{s_x}(x)\ge c\theta,\qquad
 \nu_{\sqrt2s_x}(x)\le C\theta,\qquad
 h_{u_x}(x)\le C\theta,
\end{equation}
where $\theta>0$ and the constants are fixed.  There is a
fixed $L_0$ such that, if $B_{L_0s_x}(x)\subset E$ for every
contact, then
\begin{equation}\label{pk:charge-bound}
 h^*(\mathcal C)\le C\nu(E).
\end{equation}
Here $E$ is Borel and $h^*$ is outer measure.  The statement
also holds for a submeasure of a contact measure whose spatial
projection is dominated by $h$.
\end{lemma}

\begin{proposition}\label{prop:initial}
After constant rescaling, the metrics in \eqref{eq:sequence} satisfy
\begin{equation}\label{eq:normalization}
 \frac1V\int_M R\dd=12,\qquad
 \norm{R-12}_2\le4\norm E_2,\qquad
 \norm{\Ric-3g}_2\longrightarrow0,
\end{equation}
where $V=\Vol(M,g)$. There are uniform positive constants
$v_0,V_0,D_0$ such that
\begin{equation}\label{eq:initial-geometry}
 v_0\le V\le V_0,\qquad \diam(M,g)\le D_0.
\end{equation}
\end{proposition}

\begin{proposition}\label{prop:initial-sobolev}
The normalized metrics of Proposition~\ref{prop:initial} satisfy
\begin{equation}\label{eq:initial-sobolev}
 \norm f_4^2\le S\int_M(|\nabla f|^2+f^2)\dd
\end{equation}
for all Lipschitz functions $f$, with a uniform constant $S$.
\end{proposition}

\begin{proposition}\label{prop:weighted}
There is a uniform $S_1$ such that, whenever
$0\le t<\min\{1,\mathcal T_j\}$,
\begin{equation}\label{eq:weighted}
 \norm f_4^2\le S_1\int_M\bigl(4|\nabla f|^2+(R+1)f^2\bigr)\dd
\end{equation}
for every Lipschitz function $f$ on $(M_j,g_j(t))$.
\end{proposition}

\begin{proposition}\label{prop:tail}
After discarding finitely many indices, there are uniform constants
$S_2,C$ such that, for $0\le t<\min\{T,\mathcal T_j\}$,
\begin{align}
 \norm f_4^2&\le S_2\int_M(|\nabla f|^2+f^2)\dd,
       \label{eq:flow-sobolev}\\
 \int_M w_j(t)^2\dd&\le e^{Ct}\int_M w_j(0)^2\,d\mu_{g_j},
       \label{eq:tail-propagation}\\
 \int_M|\Rm_{g_j(t)}|^2\dd&\le C.
       \label{eq:curvature-energy}
\end{align}
The Sobolev estimate holds for every Lipschitz function $f$.
In particular, the supremum of $\norm{w_j(t)}_2$ over these existing
times tends to zero.
\end{proposition}

\begin{lemma}\label{lem:noncollapse}
There is a uniform $v_*>0$ such that at every time covered by
Proposition~\ref{prop:tail},
\begin{equation}\label{eq:noncollapse}
 \Vol_{g_j(t)}B_{g_j(t)}(x,r)\ge v_*r^4
 \quad\text{for all }x\in M_j,\quad 0<r\le1.
\end{equation}
\end{lemma}

\begin{proposition}\label{prop:smoothing}
For all sufficiently large $j$, the flow $g_j(t)$ exists on $[0,T]$.
There is a uniform constant $A$ such that
\begin{equation}\label{eq:curvature-bound}
 \max_{M_j}|\Rm_{g_j(t)}|\le\frac At,
 \qquad 0<t<T.
\end{equation}
\end{proposition}

\begin{proposition}\label{prop:einstein-defect}
Set $\lambda(t)=3/(1-6t)$. Along the flows above,
\begin{equation}\label{eq:einstein-defect}
 \sup_{0\le t<T}
 \norm{\Ric_{g_j(t)}-\lambda(t)g_j(t)}_{L^2(g_j(t))}
 \longrightarrow0.
\end{equation}
\end{proposition}

\begin{proposition}\label{prop:sectional-defect}
There is a uniform constant $C$ such that
\begin{equation}\label{eq:sectional-defect}
 \int_{M_j}F(\Rm_{g_j(t)})\,d\mu_{g_j(t)}\le Ct,
 \qquad 0\le t<T.
\end{equation}
\end{proposition}

\begin{lemma}[Renormalization and first variation]
\label{ell:functional}
The functional in Equation~\eqref{eq:energy-functional} is defined on
the preceding metrics.  For a variation with the same root decay,
\begin{equation}
 DE_g(\dot g)=\int\left\langle\tfrac12R(g)g-\Ric(g),\dot g\right\rangle_g
 \,d\mu_g.
 \label{ell:first-variation}
\end{equation}
It is invariant under diffeomorphisms isotopic to the identity whose
root displacement, including scaled derivatives throughout the
isotopy, is $O(r^{1-q'})$ for some $q'>1$.  A global length scaling
by $s$, accompanied by a coordinate dilation at infinity restoring
the leading tensor $\delta$, multiplies $E$ by $s^2$.
Under Equation~\eqref{eq:tree-ricci-error}, $|E(g)|\le CM$.
\end{lemma}

\begin{theorem}[Static tree inequality {\cite[Theorem~2.2]{StaticTrees}}]
\label{thm:tree-inequality}
For the fixed tree and the sequences just specified,
\begin{equation}
                         E(g)=o(M).
 \label{ell:little-oh}
\end{equation}
For $M=0$ the assertion means $E(g)=0$.
\end{theorem}

\begin{proposition}[A continuous outermost scale]\label{prop:root-scale}
There is a fixed small $c_*>0$ such that the following definition
detects the unique outermost entry. Choose a bounded continuous
$\psi:[0,1]\to[0,\infty)$, zero on $[0,c_*]$ and strictly positive
on $[2c_*,1]$, and set
\begin{equation}\label{geom:root-definition}
 a(t)=\sup_{y\in\mathcal U}
 l(y,t)\psi\big(l(y,t)^2|\Rm|(y,t)\big).
\end{equation}
After shrinking $\mathcal U$, this supremum is attained in its
interior for every late time; it is positive and continuous, and
$a(t)\to0$. For every sequence of late times, scale $a(t)$ and any
maximizing point represent the outermost nonflat entry. Every other
nonflat entry has scale bounded by a constant times $a(t)$.
The constants may be fixed after extracting the sequential tree.
\end{proposition}

\begin{lemma}[Local smoothing with time $L^p$ input]
\label{para:local-smoothing}
Consider a linear system on a regular parabolic patch, normalized to spatial
radius and temporal duration of order one, with scalar uniformly elliptic
principal part.  Suppose its spatial coefficient derivatives through a
sufficiently high fixed order are bounded.  For nested cylinders
$Q'\Subset Q$ whose evaluation times have a positive past margin, a
solution $U$ with source $F$ satisfies, for $1<p\le2$,
\begin{equation}
 \sup_{Q'}\sum_{k=0}^j|D^kU|
 \le C\left[
 \left(\frac1{|J|}\int_J\|U(\cdot,\tau)\|_{L^2(\Omega)}^p\,d\tau\right)^{1/p}
 +\left(\frac1{|J|}\int_J\|F(\cdot,\tau)\|_{H^{j+3}(\Omega)}^p\,d\tau\right)^{1/p}
 \right],
 \label{para:local-mixed}
\end{equation}
after enlarging $\Omega\times J$ inside $Q$ if necessary.  The first input
can instead be the normalized spacetime $L^p$ norm of $U$.  Constants
depend on the coefficient bounds and margins.  Corresponding time
$L^p$ estimates over longer windows follow by integrating sliding
cylinders of unit duration.
\end{lemma}

\begin{lemma}[Control of the spherical mean derivatives]
\label{para:mean-lemma}
Let $T$ be a spatially constant multiple of $\Ric$ on an annulus whose
metric has scaled $C^{j+1}$ distance at most $e$ from $\delta$.
On a fixed-width shell of radius $s$ in its Cartesian coordinates,
\begin{equation}
 \sum_{k=1}^j s^k|\nabla^kT|
 \le C_j\left(\sum_{k=1}^j s^k\sup|D^kPT|
              +e\sup|T|_{j,s}\right),
 \label{para:mean-derivatives}
\end{equation}
where the suprema on the right use a fixed enlargement of the shell.
\end{lemma}

\begin{proposition}[Exterior concentration bound]
\label{prop:exterior-ricci}
There are fixed $N_0\gg1$, $r_0>0$, and
$0<\alpha<\min(\mu,1)$, and a choice of $N_1$ in
Equation~\eqref{eq:root-energy}, such that
\begin{align}
 V(r)&\le C\left[(a/r)^{2+\alpha}K
             +\widetilde\delta_i\bigl((a/r)^\alpha+r^\alpha\bigr)\right],
 \label{para:exterior-v}\\
 A(r)&\le C\left[(a/r)^{2+\alpha}K+\widetilde\delta_i\right]
 \label{para:exterior-a}
\end{align}
for $N_0a\le r\le r_0$, where
$\widetilde\delta_i\to0$ and $\widetilde\delta_i\ge\epsilon$.
The constants are independent of $i$ and $r$.
\end{proposition}

\begin{lemma}
\label{para:maximal-lemma}
For every fixed $D_1$,
\begin{equation}
 \|H_*\|_{L^2(\R)}\le C_{D_1,p}(K+o_i(1)).
 \label{eq:maximal-ricci}
\end{equation}
\end{lemma}

\begin{theorem}[Collar extension]
\label{thm:collar-extension}
There are \(\sigma_*>0\), \(R_*<\infty\), and \(C<\infty\), depending
only on \(q,k\), the fixed shell choices, and the weight comparison
constants, with the following property.  If
\(\sigma\le\sigma_*\) and \(R\ge R_*\), there is a metric \(\bar h\)
on \(\mathcal E\) such that
\begin{equation}
\begin{split}
 \|\bar h-\delta\|_{H^k_q}
   &\le C\|g-\delta\|_{H^k(C_1)},\\
 \|g-\bar h\|_{H^k(C_1)}
    +\|\Ric(\bar h)\|_{H^{k-2}_{q+2}}
   &\le C m_1.
\end{split}
\label{eq:collar-extension}
\end{equation}
The map \(g|_{C_1}\mapsto\bar h-\delta\) is real analytic on a fixed
neighborhood of zero in collar \(H^k\), and its first derivative into
\(H^k_q\) has uniformly bounded operator norm.  It is independent of
\(R\), the weights, and the choice of an exterior realizing the collar
data.  There is also such an analytic extension \(\hat h\), equal to
\(g\) near the inner boundary, for which
\[
 \|\hat h-\delta\|_{H^k_q}\le C\|g-\delta\|_{H^k(C_1)},
 \qquad
 \|\Ric(\hat h)\|_{H^{k-2}_{q+2}}\le Cm_1,
\]
and whose first derivative has the same bound.
\end{theorem}

\begin{lemma}[Local potential and Korn estimates]
\label{collar:potential}
On a fixed smooth Euclidean annulus, ball, or fixed-width annular
overlap in dimension four, there is a bounded linear extraction
\(v\mapsto P v\in H^{k+1}\) with
\begin{equation}
 \|v-\mathcal L_{Pv}\delta\|_{H^k}
       \le C\|\mathcal K(v)\|_{H^{k-2}},
 \qquad \|Pv\|_{H^{k+1}}\le C\|v\|_{H^k}.
 \label{collar:local-potential}
\end{equation}
For vector fields on these domains,
\begin{equation}
 \inf_{W\in\mathfrak e(4)}\|V-W\|_{H^{k+1}}
           \le C\|\mathcal L_V\delta\|_{H^k},
 \label{collar:korn}
\end{equation}
where \(\mathfrak e(4)=\{x\mapsto Ax+b:A^t=-A\}\).
All choices can be linear, normalized modulo this rigid-motion
space, and equivariant.  After dilation, the right side of the first
inequality in Equation~\eqref{collar:local-potential} is multiplied
by \(r^2\), and vector norms in both inequalities are divided by \(r\).
\end{lemma}

\begin{lemma}[Newton estimates used below]
\label{collar:newton}
Let \(G(x)=c_4|x|^{-2}\) be the fundamental solution for the chosen
sign of the Euclidean Laplacian.
For \(0<q<2\), its Newton operator is bounded
\[
 \Delta^{-1}:H^{k-2}_{q+2}(\R^4)\longrightarrow H^k_q(\R^4).
\]
For \(1<q<2\), if \(h\in H^{k-3}_{q+3}(\R^4)\) and
\(\int_{\R^4}h=0\) componentwise, then
\begin{equation}
 \|\Delta^{-1}h\|_{H^{k-1}_{q+1}}
             \le C\|h\|_{H^{k-3}_{q+3}}.
 \label{collar:zero-mass-newton}
\end{equation}
Finally, on an annulus or ball of outer radius comparable to \(R\),
if \(\Delta W=H\), boundary strips control \(W\) in scaled
\(H^{k-2}\) by \(b_0\), and
\(c_r=r^2\|H\|_{H^{k-4}(r)}\), then
\begin{equation}
 \sup_r\|W\|_{H^{k-2}(r)}\le C\left(b_0+\sum_rc_r\right).
 \label{collar:green-sum}
\end{equation}
The constant is independent of the number of shells.  A filled ball
has no inner boundary term; its innermost shell is replaced by a
fixed ball.
\end{lemma}

\begin{lemma}[The time-integrated collar error]
\label{final:collar-bound}
The residual in Equation~\eqref{eq:collar-residual} for every active
patch is bounded by a common nonnegative function $m(t)$ such that
\begin{equation}\label{eq:collar-time-bound}
 \sup_{\supp\eta}m=o_i(1),\qquad
 b^{-2}\|\eta m\|_{L^2(I)}+\|\eta B_1\|_{L^2(I)}
 \le C\bigl[(a/b)^{2+\alpha}K+\rho_i\bigr],
 \quad \rho_i\longrightarrow0.
\end{equation}
The leading constant is independent of large $N$; $\rho_i$ may depend
on fixed $N$.
\end{lemma}

\begin{proposition}[Positive variation supplied by the true core]
\label{final:variation}
For the preceding extensions and partition,
\begin{equation}\label{eq:variation-lower}
 \sum_j\int_I\eta^2\chi_j E_j'\,dt
 \ge 2a^4K^2-a^4\bigl[CN^{-2\alpha}K^2
                              +o_i(1)(K+1)^2\bigr].
\end{equation}
\end{proposition}

\begin{proposition}[Uniform functional smallness]
\label{final:functional-smallness}
For fixed $N$ there are numbers $\zeta_i\to0$ such that, at every
time in every active patch,
\begin{equation}\label{eq:functional-littleoh}
 |\eta(t)E_j(t)|\le
 \zeta_i a^4\bigl[H_*(t)+1+a^{-2}\eta(t)m(t)\bigr].
\end{equation}
Here $H_*$ uses a fixed enlargement depending on $N$.
\end{proposition}

\begin{corollary}\label{final:energy-vanishes}
Along the buffered intervals, $K_i\to0$.
\end{corollary}

\begin{lemma}[A common time-dependent Ricci bound]
\label{final:ricci-envelope}
On a slightly smaller material neighborhood of the isolated cluster,
for $0\le t\le1$,
\begin{equation}\label{eq:final-ricci-bound}
 |\Ric|(y,t)\le Q_*(t)\bigl[1+(a/l(y,t))^2\bigr],
 \qquad\|Q_*\|_{L^2([0,1])}\longrightarrow0.
\end{equation}
\end{lemma}

\begin{lemma}[Good material points]
\label{final:good-points}
There is a single set of material points $\mathcal G_i$, independent
of time, whose complement has volume $o(a_i^4)$, which is $o(a_i)$-dense
at every $t\in[0,1]$ in a smaller neighborhood of the cluster.
For points $x,y\in\mathcal G_i$ in that neighborhood whose distance
at either endpoint is at most $Ca_i$,
\begin{equation}\label{final:good-distance}
 |d_1(x,y)-d_0(x,y)|=o(a_i),
\end{equation}
uniformly for each fixed $C$.
\end{lemma}

\begin{lemma}[Renormalization and first variation]
\label{ell:functional}
The functional in Equation~\eqref{eq:energy-functional} is defined on
the preceding metrics.  For a variation with the same root decay,
\begin{equation}
 DE_g(\dot g)=\int\left\langle\tfrac12R(g)g-\Ric(g),\dot g\right\rangle_g
 \,d\mu_g.
 \label{ell:first-variation}
\end{equation}
It is invariant under diffeomorphisms isotopic to the identity whose
root displacement, including scaled derivatives throughout the
isotopy, is $O(r^{1-q'})$ for some $q'>1$.  A global length scaling
by $s$, accompanied by a coordinate dilation at infinity restoring
the leading tensor $\delta$, multiplies $E$ by $s^2$.
Under Equation~\eqref{eq:tree-ricci-error}, $|E(g)|\le CM$.
\end{lemma}

\begin{theorem}[Tree inequality]
\label{thm:tree-inequality}
Fix a finite rooted tree with the end identifications and order-$20$ metric bounds of Section~\ref{ell:setup}. Let $(g_j,L^{(j)},M_j)$ satisfy the compact vertex convergence, the same uniform half-end and root-end bounds, and Equation~\eqref{eq:tree-ricci-error} through order $10$, with every $L_e^{(j)}\to\infty$ and $M_j\to0$. Then, in physical root units,
\begin{equation}
                         E(g_j)=o(M_j).
 \label{ell:little-oh}
\end{equation}
For an index with $M_j=0$, the assertion means $E(g_j)=0$. The little-oh is taken for this fixed tree; it does not assert a power exponent uniform over different trees.
\end{theorem}

\begin{lemma}[Sector uniqueness]\label{path:sector-uniqueness}
Suppose \(f\) is bounded and holomorphic on an admissible sector and, on
the central subsector \(|\arg z|\le\pi/4\), satisfies
\(f(z)=O_B(e^{-B|z|})\) for every \(B>0\).  Then \(f=0\).
\end{lemma}

\begin{lemma}[Roots in a regular scalar system]\label{path:roots}
Suppose \textup{(R1)--(R3)} hold, including divisibility of positive
sizes.  Then the complex scalar field is algebraically closed and its
real part is real closed.
\end{lemma}

\begin{lemma}[Detection of analytic identities]\label{path:detection}
Path families with the submersivity property in \textup{(R4)} detect
analytic germs.  Namely, if an analytic function vanishes on the tail
of every path in such a family, then it vanishes as a domain germ.
The same holds for a holomorphic family in extra ordinary variables.
\end{lemma}

\begin{lemma}[Contours and complex inverses]
\label{ell:complex-inverse}
For some $A,c_0>0$ the inverse of Lemma~\ref{ell:seam-inverse}
continues to
\begin{equation}
 \Re L_e>A,\qquad |\Im L_e|<c_0(\Re L_e)^2.
 \label{ell:quadratic-domain}
\end{equation}
The field norm is measured on increasing-real-part contours.
One strengthens the source norm on the portion
$u\ge\Re L_e/5$ and the seam norm by a fixed polynomial in
$1+\Re L_e$.  With these norms the inverse is uniform.
The same assertion holds for opened ends continued along such
contours and for every partial disconnection.
\end{lemma}

\begin{lemma}[Gauge for the real sequence]
\label{ell:gauge}
After a diffeomorphism of the invariance class in
Lemma~\ref{ell:functional}, each sufficiently late metric in the
sequence satisfies
\begin{equation}
 W_b(g)=m\cdot\psi,
 \label{ell:gauge-equation}
\end{equation}
where $\psi$ is the finite list of vector augmentation sources,
rescaled in physical units, and $m$ is small.  The gauged metric
retains Equation~\eqref{eq:tree-ricci-error} in weaker admissible
weights and is close to $b$ at the joining weight $\gamma_g$.
\end{lemma}

\begin{lemma}[Comparison with the actual metric]
\label{ell:comparison}
Choose $z$ from the core tests and gauge coefficients of $g$, and
from Equation~\eqref{ell:seam-prescription} at its seams.  Then
\begin{equation}
 \|g-h_*\|_{X^k_\nu}\le CM,\qquad
 \|\Ric(h_*)\|_{Y^{k-2}_\nu}\le CM,\qquad
 |E(g)-E(h_*)|\le CM^2.
 \label{ell:comparison-estimates}
\end{equation}
\end{lemma}

\begin{lemma}[Differential of the scalar observable]
\label{ell:differential}
On the real small family, for some $c>0$,
\begin{equation}
 |dF|\le C\sqrt J\left(\sum_\alpha|dz_\alpha|
                 +\sum_e e^{-cL_e}|dL_e|\right).
 \label{ell:dF}
\end{equation}
\end{lemma}

\begin{proposition}[Differential equations for the Weyl blocks]
\label{prop:weyl-derivative-equations}
The tensor $Z=\nabla T$ belongs to the parallel subbundle
$G$ of type $(5/2,1/2)$. On this bundle, put
$B_{\mathrm{op}}=Q_{5/2}(T)$. Then
\[
 \Delta T=6(T-N),\qquad
 N=(T^2)_0=T^2-2v^2\operatorname{Id},
\]
and
\begin{equation}
 \Delta Z=(13-20B_{\mathrm{op}})Z.
 \tag{1}\label{eq:1}
\end{equation}
Every statement has an exchanged counterpart for $U$.
\end{proposition}

\begin{lemma}[Parametrization of the Bianchi gradient space]
\label{lem:gradient-parametrization}
There are unique vectors $k,l$ such that
\begin{equation}
 \begin{gathered}
 Z_{ii}=s_i p-\sqrt3\,\widetilde s_i k,\qquad
 Z_{jk}=-I_i\left(l+s_i k+\frac{\widetilde s_i}{\sqrt3}p\right),
 \qquad (i,j,k)\ \text{cyclic},\\
 e=\frac53|p|^2+5|k|^2+|l|^2.
 \end{gathered}
 \tag{2}\label{eq:2}
\end{equation}
More generally, for any fixed normalized trace-free diagonal triple
$s$, the same formulas parametrize the entire algebraic space $G$
by three arbitrary real four-vectors.
\end{lemma}

\begin{proposition}[Weak norm equation, including the zero set]
\label{prop:weak-norm-equation}
The function $e/v$, defined to be zero on $\{v=0\}$, belongs to
$L^1(M)$, and
\begin{equation}
 \Delta v=6v(1-\sigma v)+\frac{e-|p|^2}{v}
 \tag{3}\label{eq:3}
\end{equation}
holds as an equality of distributions with an $L^1$ density.
The quotient is zero almost everywhere on the zero set.
This identity may be tested against bounded Lipschitz functions.
The corresponding assertions hold for $b$.
\end{proposition}

\begin{proposition}[Weighted variance]
\label{prop:weighted-variance}
For every real $a\in H^1(M)$,
\begin{equation}
 \operatorname{Var}(a)
 :=\mathbf E\bigl[(a-\mathbf E a)^2\bigr]
 \le\mathbf E\frac{|\nabla a|^2}{K},
 \qquad K=4+v^2+b^2.
 \tag{4}\label{eq:4}
\end{equation}
\end{proposition}

\begin{proposition}[Normalized Sobolev inequality]
\label{prop:sharp-sobolev}
For every real $f\in H^1(M)$,
\[
 \bigl(\mathbf E|f|^4\bigr)^{1/2}
 \le\mathbf E\left(f^2+\frac12|\nabla f|^2\right).
\]
\end{proposition}

\begin{proposition}[Weyl-norm gap]
\label{prop:weyl-gap}
For either Weyl block,
\begin{equation}
 v\equiv0\qquad\text{or}\qquad \mathbf E v^2\ge1.
 \tag{5}\label{eq:5}
\end{equation}
If $T\not\equiv0$ and $\mathbf E v^2=1$, then
$\nabla T=0$ and $v=\sigma=1$. The corresponding statements hold
for $U$.
\end{proposition}

\begin{proposition}[Characteristic identities]
\label{prop:characteristic-identities}
Let $n_+$ and $n_-$ be the finite nonnegative integer dimensions of
the spaces of harmonic self-dual and anti-self-dual two-forms. The Euler
characteristic and signature of $M$ are, respectively,
\[
 \chi=2+n_++n_-,\qquad \tau=n_+-n_-.
\]
Then
\begin{equation}
 \begin{aligned}
 8\pi^2\chi
   &=6\operatorname{Vol}(M)
        \bigl(1+\mathbf E(v^2+b^2)\bigr),\\
 12\pi^2\tau
   &=6\operatorname{Vol}(M)\,\mathbf E(v^2-b^2).
 \end{aligned}
 \tag{6}\label{eq:6}
\end{equation}
If $U=0$, then $n_-=0$; likewise $T=0$ implies $n_+=0$.
\end{proposition}

\begin{proposition}[Upper volume deficit]\label{prop:upper-volume-deficit}
One has
\[
 \frac{V_M}{8\pi^2/3}\le 1-\frac{3}{40}s_0.
 \tag{7}\label{eq:7}
\]
\end{proposition}

\begin{lemma}[Geodesic averages]\label{lem:geodesic-averages}
At every time along the geodesic flow,
\[
 \mathcal E|A|^2=\frac32s_0,\qquad
 \mathcal E|A'|^2\le\frac32\,\mathcal E|A|^2.
 \tag{8}\label{eq:8}
\]
\end{lemma}

\begin{lemma}[Diameter, injectivity, and topology]\label{lem:volume-topology}
The diameter of $M$ is at most $\pi$, its injectivity radius is at least
$\pi/\sqrt3$, and $M$ is simply connected. Every minimizing geodesic
segment has no point conjugate to its initial point in its interior.
\end{lemma}

\begin{lemma}[Upper polar bound]\label{lem:upper-polar}
One has
\[
 V_M\le2\pi^2\int_0^\pi\mathcal E D_c(t)\,dt.
\]
\end{lemma}

\begin{proposition}[Balanced Weyl moments]\label{prop:balanced-moments}
If neither Weyl block is identically zero, then
$\tau=0$ and $\mathbf E v^2=\mathbf E b^2$.
\end{proposition}

\begin{proposition}[Weighted Hessian inequality]
\label{prop:weighted-hessian}
For every global Lipschitz scalar weight \mbox{$m\ge m_0>0$},
\begin{equation}
 0\le\mathbf E\left[
 mG_v(p,k,l)
 -\frac56\sum_i m_i\,
    \frac{\operatorname{tr}\bigl(Z_i\sum_jZ_j^2\bigr)}6
 +\frac{\langle\mathcal P(L_m)_Y,(L_m)_Y\rangle}{24m}
 \right],
 \tag{10}\label{eq:10}
\end{equation}
where \(i,j\) in the middle term are derivative indices and
\[
 G_v=\left(-42-3b^2-\frac{10}{3}v^2\right)e
       +75B+\frac{25}{3}C_N-\frac{100}{3}E_B
       +5v^2|p|^2.
\]
\end{proposition}

\begin{lemma}[The quadratic-form matrices]
\label{lem:hessian-matrices}
At a point where \(v>0\), use the three vector parameters \(p,k,l\) in
\eqref{eq:2}.  Then \(G_v\) is the quadratic form, with scalar entries
multiplying vector dot products, whose matrix is
\begin{equation}
 \begin{pmatrix}
 -70-5b^2+100\sigma v-25v^2
   &-100\sqrt3\rho v&-35\rho v^2/\sqrt3\\
 -100\sqrt3\rho v
   &-210-15b^2-300\sigma v-190v^2&-75v-35\sigma v^2\\
 -35\rho v^2/\sqrt3
   &-75v-35\sigma v^2&-42-3b^2-10v^2
 \end{pmatrix}.
 \tag{11}\label{eq:11}
\end{equation}
\end{lemma}

\begin{lemma}[The cubic contraction]
\label{lem:cubic-contraction}
For every real tangent vector \(a\), with
\(Z_a=\sum_i a_iZ_i\),
\begin{equation}
 \left|\frac{\operatorname{tr}\bigl(Z_a\sum_jZ_j^2\bigr)}6\right|
 \le \frac45\sqrt{\frac35}\,|a|e^{3/2}.
 \tag{13}\label{eq:13}
\end{equation}
\end{lemma}

\begin{proposition}[The projection cost]
\label{prop:hessian-projection-cost}
For the weight \eqref{eq:12},
\begin{equation}
 \frac{\langle\mathcal P(L_m)_Y,(L_m)_Y\rangle}{24m}
 \le\frac9{64}|p-q|^2
       \left[\frac7{12}(4+y)e-\frac54B\right].
 \tag{14}\label{eq:14}
\end{equation}
The bracket on the right is nonnegative.  Both assertions remain valid
under the closed inequalities \(v+b\le2\) and \(x+y\le2\).
\end{proposition}

\begin{lemma}[The polynomial $F$]\label{lem:potential-certificate}
The polynomial $F=cE_0-\Theta^2$ is nonnegative on $\mathcal D$.
\end{lemma}

\begin{proposition}[Half-conformal flatness]\label{prop:one-block-vanishes}
At least one of $T,U$ vanishes identically; equivalently, the metric is
half-conformally flat.
\end{proposition}

\begin{proposition}[Conditional lower volume bound]
\label{prop:conditional-lower-volume}
If $s_0=\mathbf E(v^2+b^2)=3$, then $V_M>4\pi^2/3$.
\end{proposition}

\begin{lemma}[Lower polar bound]\label{lem:lower-polar}
One has
\[
 V_M\ge2\pi^2\int_0^{\pi/\sqrt3}\mathcal E D(t)\,dt.
\]
\end{lemma}

\begin{proposition}[The remaining parallel tensors]\label{prop:parallel-models}
Up to reversing orientation, either $T=U=0$, or $U=0$ and $T$ is parallel
with eigenvalues $2,-1,-1$.
\end{proposition}

\begin{lemma}[Curvature of the standard models]\label{lem:model-curvature}
The two tensors in Proposition~\ref{prop:parallel-models} are the curvature tensors of the unit round sphere and of twice the Fubini--Study metric induced by the Hopf quotient of the unit sphere $S^5\subset\mathbb C^3$.
\end{lemma}

\begin{lemma}[Global continuation of the model isometry]\label{lem:global-isometry}
The local identifications furnished by Lemma~\ref{lem:model-curvature} extend to global isometries.
\end{lemma}

\begin{proposition}[Differential equations for the Weyl blocks]
\label{prop:weyl-derivative-equations}
The tensor $Z=\nabla T$ belongs to the parallel subbundle
$G$ of type $(5/2,1/2)$. On this bundle, put
$B_{\mathrm{op}}=Q_{5/2}(T)$. Then
\[
 \Delta T=6(T-N),\qquad
 N=(T^2)_0=T^2-2v^2\operatorname{Id},
\]
and
\begin{equation}
 \Delta Z=(13-20B_{\mathrm{op}})Z.
 \tag{1}\label{eq:1}
\end{equation}
Every statement has an exchanged counterpart for $U$.
\end{proposition}

\begin{lemma}[Parametrization of the Bianchi gradient space]
\label{lem:gradient-parametrization}
There are unique vectors $k,l$ such that
\begin{equation}
 \begin{gathered}
 Z_{ii}=s_i p-\sqrt3\,\widetilde s_i k,\qquad
 Z_{jk}=-I_i\left(l+s_i k+\frac{\widetilde s_i}{\sqrt3}p\right),
 \qquad (i,j,k)\ \text{cyclic},\\
 e=\frac53|p|^2+5|k|^2+|l|^2.
 \end{gathered}
 \tag{2}\label{eq:2}
\end{equation}
More generally, for any fixed normalized trace-free diagonal triple
$s$, the same formulas parametrize the entire algebraic space $G$
by three arbitrary real four-vectors.
\end{lemma}

\begin{proposition}[Weak norm equation, including the zero set]
\label{prop:weak-norm-equation}
The function $e/v$, defined to be zero on $\{v=0\}$, belongs to
$L^1(M)$, and
\begin{equation}
 \Delta v=6v(1-\sigma v)+\frac{e-|p|^2}{v}
 \tag{3}\label{eq:3}
\end{equation}
holds as an equality of distributions with an $L^1$ density.
The quotient is zero almost everywhere on the zero set.
This identity may be tested against bounded Lipschitz functions.
The corresponding assertions hold for $b$.
\end{proposition}

\begin{proposition}[Weighted variance]
\label{prop:weighted-variance}
For every real $a\in H^1(M)$,
\begin{equation}
 \operatorname{Var}(a)
 :=\mathbf E\bigl[(a-\mathbf E a)^2\bigr]
 \le\mathbf E\frac{|\nabla a|^2}{K},
 \qquad K=4+v^2+b^2.
 \tag{4}\label{eq:4}
\end{equation}
\end{proposition}

\begin{proposition}[Normalized Sobolev inequality]
\label{prop:sharp-sobolev}
For every real $f\in H^1(M)$,
\[
 \bigl(\mathbf E|f|^4\bigr)^{1/2}
 \le\mathbf E\left(f^2+\frac12|\nabla f|^2\right).
\]
\end{proposition}

\begin{proposition}[Weyl-norm gap]
\label{prop:weyl-gap}
For either Weyl block,
\begin{equation}
 v\equiv0\qquad\text{or}\qquad \mathbf E v^2\ge1.
 \tag{5}\label{eq:5}
\end{equation}
If $T\not\equiv0$ and $\mathbf E v^2=1$, then
$\nabla T=0$ and $v=\sigma=1$. The corresponding statements hold
for $U$.
\end{proposition}

\begin{proposition}[Characteristic identities]
\label{prop:characteristic-identities}
Let $n_+$ and $n_-$ be the finite nonnegative integer dimensions of
the spaces of harmonic self-dual and anti-self-dual two-forms. The Euler
characteristic and signature of $M$ are, respectively,
\[
 \chi=2+n_++n_-,\qquad \tau=n_+-n_-.
\]
Then
\begin{equation}
 \begin{aligned}
 8\pi^2\chi
   &=6\operatorname{Vol}(M)
        \bigl(1+\mathbf E(v^2+b^2)\bigr),\\
 12\pi^2\tau
   &=6\operatorname{Vol}(M)\,\mathbf E(v^2-b^2).
 \end{aligned}
 \tag{6}\label{eq:6}
\end{equation}
\end{proposition}

\begin{proposition}[Upper volume deficit]\label{prop:upper-volume-deficit}
One has
\[
 \frac{V_M}{8\pi^2/3}\le 1-\frac{3}{40}s_0.
 \tag{7}\label{eq:7}
\]
\end{proposition}

\begin{lemma}[Geodesic averages]\label{lem:geodesic-averages}
At every time along the geodesic flow,
\[
 \mathcal E|A|^2=\frac32s_0,\qquad
 \mathcal E|A'|^2\le\frac32\,\mathcal E|A|^2.
 \tag{8}\label{eq:8}
\]
\end{lemma}

\begin{lemma}[Upper polar bound]\label{lem:upper-polar}
One has
\[
 V_M\le2\pi^2\int_0^\pi\mathcal E D_c(t)\,dt.
\]
\end{lemma}

\begin{proposition}[Balanced Weyl moments]\label{prop:balanced-moments}
If neither Weyl block is identically zero, then
$\tau=0$ and $\mathbf E v^2=\mathbf E b^2$.
\end{proposition}

\begin{proposition}[Weighted Hessian inequality]
\label{prop:weighted-hessian}
For every global Lipschitz scalar weight \mbox{$m\ge m_0>0$},
\begin{equation}
 0\le\mathbf E\left[
 mG_v(p,k,l)
 -\frac56\sum_i m_i\,
    \frac{\operatorname{tr}\bigl(Z_i\sum_jZ_j^2\bigr)}6
 +\frac{\langle\mathcal P(L_m)_Y,(L_m)_Y\rangle}{24m}
 \right],
 \tag{10}\label{eq:10}
\end{equation}
where \(i,j\) in the middle term are derivative indices and
\[
 G_v=\left(-42-3b^2-\frac{10}{3}v^2\right)e
       +75B+\frac{25}{3}C_N-\frac{100}{3}E_B
       +5v^2|p|^2.
\]
More precisely, if $\mathcal W_v(m)$ denotes the integrand in
\eqref{eq:10}, then the exact identity is
\begin{equation}
 \mathbf E\mathcal W_v(m)
 =\mathbf E\left[\frac m6\left\langle
 \mathcal P\left(Y+\frac{(L_m)_Y}{2m}\right),
               Y+\frac{(L_m)_Y}{2m}\right\rangle\right].
 \tag{10a}\label{eq:weighted-hessian-square}
\end{equation}
\end{proposition}

\begin{lemma}[The quadratic-form matrices]
\label{lem:hessian-matrices}
At a point where \(v>0\), use the three vector parameters \(p,k,l\) in
\eqref{eq:2}.  Then \(G_v\) is the quadratic form, with scalar entries
multiplying vector dot products, whose matrix is
\begin{equation}
 \begin{pmatrix}
 -70-5b^2+100\sigma v-25v^2
   &-100\sqrt3\rho v&-35\rho v^2/\sqrt3\\
 -100\sqrt3\rho v
   &-210-15b^2-300\sigma v-190v^2&-75v-35\sigma v^2\\
 -35\rho v^2/\sqrt3
   &-75v-35\sigma v^2&-42-3b^2-10v^2
 \end{pmatrix}.
 \tag{11}\label{eq:11}
\end{equation}
\end{lemma}

\begin{lemma}[The cubic contraction]
\label{lem:cubic-contraction}
For every real tangent vector \(a\), with
\(Z_a=\sum_i a_iZ_i\),
\begin{equation}
 \left|\frac{\operatorname{tr}\bigl(Z_a\sum_jZ_j^2\bigr)}6\right|
 \le \frac45\sqrt{\frac35}\,|a|e^{3/2}.
 \tag{13}\label{eq:13}
\end{equation}
\end{lemma}

\begin{proposition}[The projection cost]
\label{prop:hessian-projection-cost}
For the weight \eqref{eq:12},
\begin{equation}
 \frac{\langle\mathcal P(L_m)_Y,(L_m)_Y\rangle}{24m}
 \le\frac9{64}|p-q|^2
       \left[\frac7{12}(4+y)e-\frac54B\right].
 \tag{14}\label{eq:14}
\end{equation}
The bracket on the right is nonnegative.  Both assertions remain valid
under the closed inequalities \(v+b\le2\) and \(x+y\le2\).
\end{proposition}

\begin{lemma}[The polynomial $F$]\label{lem:potential-certificate}
The polynomial $F=cE_0-\Theta^2$ is nonnegative on $\mathcal D$.
\end{lemma}

\begin{proposition}[Constancy of the two Weyl norms]
\label{prop:constant-norms}
On a closed, simply connected, oriented four-manifold with
$\operatorname{Ric}=3g$, nonnegative sectional curvature, and neither
Weyl block identically zero, one has $v=b=1$ everywhere.
\end{proposition}

\begin{proposition}[Parallel Weyl blocks]\label{prop:parallel-blocks}
Both $T$ and $U$ are parallel, with eigenvalues $(2,-1,-1)$.
\end{proposition}
